package com.guocheng.mediapocket;
import android.app.Activity;import android.content.*;import android.view.*;import android.widget.FrameLayout;import android.widget.Toast;
/** 把高刷和缓冲速度接到正在播放的画面上。 */
final class PlayerSwitches {
 static final java.util.Map<Activity,String> BUFFER=new java.util.WeakHashMap<>();
 static final java.util.WeakHashMap<Activity,Boolean> REFRESH=new java.util.WeakHashMap<>();
 private PlayerSwitches(){}
 static void tick(Activity a){if(a==null||a.isFinishing())return;applyRefresh(a);if(PlaybackPrefs.showBufferSpeed(a.getSharedPreferences("data",0)))BUFFER.put(a,readBuffer(a));else BUFFER.remove(a);}
 static String buffer(Activity a){String v=BUFFER.get(a);return v==null?"":v;}
 static String readBuffer(Activity a){try{Object video=OnlineSubtitleSearch.field(a,"video");Object player=video==null?null:OnlineSubtitleSearch.field(video,"player");float rate=bitrate(player);if(rate<0)rate=bitrate(video);return PlayerSwitchRules.buffer(rate);}catch(Exception e){return "";}}
 static float bitrate(Object player){if(player==null)return -1f;try{Object media=OnlineSubtitleSearch.call(player,"getMedia",new Class<?>[0]);Object stats=media==null?null:OnlineSubtitleSearch.call(media,"getStats",new Class<?>[0]);if(stats==null)stats=OnlineSubtitleSearch.call(player,"getStats",new Class<?>[0]);if(stats==null)return -1f;Object v=OnlineSubtitleSearch.field(stats,"demuxBitrate");if(!(v instanceof Float)||(Float)v<=0f)v=OnlineSubtitleSearch.field(stats,"inputBitrate");return v instanceof Float?(Float)v:-1f;}catch(Exception e){return -1f;}}
 static void applyRefresh(Activity a){boolean on=PlaybackPrefs.forceHighRefresh(a.getSharedPreferences("data",0));Boolean applied=REFRESH.get(a);if(applied!=null&&applied==on)return;REFRESH.put(a,on);try{android.view.Display display=a.getWindowManager().getDefaultDisplay();android.view.Display.Mode[] modes=display.getSupportedModes();android.view.Display.Mode current=display.getMode();int[] w=new int[modes.length],h=new int[modes.length];float[] r=new float[modes.length];for(int i=0;i<modes.length;i++){w[i]=modes[i].getPhysicalWidth();h[i]=modes[i].getPhysicalHeight();r[i]=modes[i].getRefreshRate();}WindowManager.LayoutParams lp=a.getWindow().getAttributes();float frame=0f;if(on){int idx=PlayerSwitchRules.fastestMode(w,h,r,current.getPhysicalWidth(),current.getPhysicalHeight(),current.getRefreshRate());if(idx>=0){lp.preferredDisplayModeId=modes[idx].getModeId();frame=modes[idx].getRefreshRate();}}else lp.preferredDisplayModeId=0;a.getWindow().setAttributes(lp);frame(a,frame);}catch(Exception ignored){}}
 static void frame(Activity a,float rate){if(android.os.Build.VERSION.SDK_INT<30)return;try{Object video=OnlineSubtitleSearch.field(a,"video");Object surface=video==null?null:OnlineSubtitleSearch.field(video,"surface");if(!(surface instanceof android.view.SurfaceView))return;android.view.Surface s=((android.view.SurfaceView)surface).getHolder().getSurface();if(s!=null&&s.isValid())s.setFrameRate(rate,android.view.Surface.FRAME_RATE_COMPATIBILITY_DEFAULT);}catch(Exception ignored){}}
 static void restoreBrightness(Activity a){if(!PlaybackPrefs.rememberBrightness(a.getSharedPreferences("data",0)))return;float b=a.getSharedPreferences("data",0).getFloat("pref.brightness",-1f);if(b<0.01f||b>1f)return;WindowManager.LayoutParams w=a.getWindow().getAttributes();w.screenBrightness=b;a.getWindow().setAttributes(w);}
 static void saveBrightness(Activity a){if(a==null||!PlaybackPrefs.rememberBrightness(a.getSharedPreferences("data",0)))return;float b=a.getWindow().getAttributes().screenBrightness;if(b>=0.01f&&b<=1f)a.getSharedPreferences("data",0).edit().putFloat("pref.brightness",b).apply();}
 static void toast(Activity a,String text){try{Toast.makeText(a,text,Toast.LENGTH_SHORT).show();}catch(Exception ignored){}}
}
